create table script_4 as
select FSYM_ID, iso_country, dev, neg_dev, pos_dev, FREQ, avgPR, CROSS_2, CROSS_1, FIRST_PRICE_DATE, FF_ISCOMP, FF_GEN_IND, 
	   max(FF_FYR) as max_FF_FYR, avg(FF_FYR) as avg_FF_FYR, min(FF_FYR) as min_FF_FYR, count(FF_FYR) as cnt,
avg(tot) as tot, avg(tot_6) as tot_6, avg(AT) as AT, avg(MKT) as MKT, avg(TOBq) as TOBq, avg(REVT) as REVT, avg(AUD_FEES) as AUD_FEES, avg(roa) as roa, avg(roe) as roe, avg(BtoP) as BtoP, avg(BtoA) as BtoA, avg(RE_BE) as RE_BE, avg(RE_AT) as RE_AT, avg(loss) as loss, 
avg(ACC) as ACC, avg(AUD_AT) as AUD_AT, avg(sACC) as sACC, std(oper)/std(CFO) as CF_ACC, sum(ACC)/sum(CFO) as ACC_ratio,
max(tot) as x_tot, max(AT) as x_AT, max(MKT) as x_MKT, max(TOBq) as x_TOBq, max(REVT) as x_REVT, max(AUD_FEES) as x_AUD_FEES, max(roa) as x_roa, max(roe) as x_roe, max(BtoP) as x_BtoP, max(BtoA) as x_BtoA, max(RE_BE) as x_RE_BE, max(RE_AT) as x_RE_AT,
min(tot) as n_tot, min(AT) as n_AT, min(MKT) as n_MKT, min(TOBq) as n_TOBq, min(REVT) as n_REVT, min(AUD_FEES) as n_AUD_FEES, min(roa) as n_roa, min(roe) as n_roe, min(BtoP) as n_BtoP, min(BtoA) as n_BtoA, min(RE_BE) as n_RE_BE, min(RE_AT) as n_RE_AT,
(calculated x_AT) - (calculated n_AT) as d_AT, (calculated x_MKT) - (calculated n_MKT) as d_MKT, (calculated x_TOBq) - (calculated n_TOBq) as d_TOBq, 
(calculated x_REVT) - (calculated n_REVT) as d_REVT, (calculated x_roa) - (calculated n_roa) as d_roa, (calculated x_AUD_FEES) - (calculated n_AUD_FEES) as d_AUD_FEES, (calculated x_roe) - (calculated n_roe) as d_roe,
(calculated x_BtoP) - (calculated n_BtoP) as d_BtoP, (calculated x_BtoA) - (calculated n_BtoA) as d_BtoA, (calculated x_RE_BE) - (calculated n_RE_BE) as d_RE_BE, (calculated x_RE_AT) - (calculated n_RE_AT) as d_RE_AT,
AVG(std12) AS STD_RET, AVG(FPE_numest) AS NUM_EST, AVG(FPE_DISP1) AS DISP, AVG(ABS(FPE_FE1)) AS ABSFE, std(oper) as std_roa,
AVG(AVG_numest) AS ANUM_EST, AVG(AVG_DISP1) AS ADISP, AVG(ABS(AVG_FE1)) AS AABSFE,
avg(iss_dt) as iss_dt, avg(iss_dt_at) as iss_dt_at, avg(iss_eq) as iss_eq, avg(iss_eq_at) as iss_eq_at, avg(iss_eq > 0) as iss_cnt
from script_4
GROUP BY FSYM_ID, iso_country, dev, neg_dev, pos_dev, FREQ, avgPR, CROSS_2, CROSS_1, FIRST_PRICE_DATE, FF_ISCOMP, FF_GEN_IND;
